import { mkdir, writeFile } from "node:fs/promises";
import { join } from "node:path";
import { pathToFileURL } from "node:url";
import { transform } from "esbuild";
import { beforeAll, describe, expect, it } from "vitest";
import { generate } from "../src/emit.js";
import { fromJSON } from "../src/fetchers/json.js";

/**
 * Deep feature coverage: minSelect, custom id, email/url domains, autogenerated
 * create-optionality, hidden-field exclusion, and typed expand across forward,
 * self-referential, multi, and unique-indexed back-relations.
 */

const tmpDir = join("test", ".tmp");
let src = "";
// dynamically imported generated module
let mod: any;

beforeAll(async () => {
  const collections = await fromJSON("test/fixtures/features_schema.json");
  const [file] = generate(collections, { zod: 4 });
  src = file!.content;
  const { code } = await transform(src, { loader: "ts", format: "esm", target: "node22" });
  await mkdir(tmpDir, { recursive: true });
  const out = join(tmpDir, "features-generated.mjs");
  await writeFile(out, code, "utf8");
  mod = await import(pathToFileURL(out).href);
});

describe("emitted source — new field features", () => {
  it("relation minSelect + maxSelect", () => {
    expect(src).toContain("reviewers: z.array(RecordIdString).min(2).max(5).optional(),");
  });

  it("autogenerated field is optional in the Record (create) schema despite required", () => {
    const recordBlock = src.slice(
      src.indexOf("export const PostsRecordSchema"),
      src.indexOf("export const PostsResponseSchema"),
    );
    expect(recordBlock).toContain("slug: z.string().optional(),");
    // title (required, not autogenerated) stays required
    expect(recordBlock).toContain("title: z.string().min(3),");
  });

  it("email/url domain refine", () => {
    expect(src).toContain("new URL(v).hostname.toLowerCase()");
    expect(src).toContain('["example.com"]');
  });

  it("hidden non-system field is excluded everywhere", () => {
    expect(src).not.toContain("secret:");
  });

  it("customized primary key emits explicit constraints", () => {
    // profiles.id: length 10 + custom pattern
    expect(src).toContain('id: z.string().length(10).regex(new RegExp("^p[a-z0-9]+$")),');
  });
});

describe("emitted source — typed expand graph", () => {
  it("self-referential relation (categories.parent)", () => {
    expect(src).toContain("parent: CategoriesResponseSchema.optional(),");
    expect(src).toContain("categories_via_parent: z.array(CategoriesResponseSchema).optional(),");
  });

  it("unique-indexed relation resolves as a SINGLE back-relation object", () => {
    // profiles.author has a UNIQUE index -> authors.expand.profiles_via_author is a single object
    expect(src).toContain("profiles_via_author: ProfilesResponseSchema.optional(),");
    expect(src).not.toContain("profiles_via_author: z.array");
    // non-unique back-relation stays an array
    expect(src).toContain("posts_via_author: z.array(PostsResponseSchema).optional(),");
  });
});

describe("generated Zod executes on recursive/expanded data", () => {
  it("parses a self-referential nested category expand", () => {
    const rec = {
      id: "cat1234567890ab",
      title: "Root",
      created: "2026-01-01 00:00:00.000Z",
      collectionId: "categories00001",
      collectionName: "categories",
      expand: {
        parent: {
          id: "cat0000000000ab",
          title: "Grandparent",
          created: "2026-01-01 00:00:00.000Z",
          collectionId: "categories00001",
          collectionName: "categories",
        },
      },
    };
    expect(mod.CategoriesResponseSchema.safeParse(rec).success).toBe(true);
  });

  it("accepts a single-object unique back-relation and rejects an array there", () => {
    const author = {
      id: "aut1234567890ab",
      email: "a@b.com",
      emailVisibility: true,
      verified: true,
      created: "2026-01-01 00:00:00.000Z",
      updated: "2026-01-01 00:00:00.000Z",
      collectionId: "authors00000001",
      collectionName: "authors",
      expand: {
        profiles_via_author: {
          id: "p123456789",
          author: "aut1234567890ab",
          created: "2026-01-01 00:00:00.000Z",
          collectionId: "profiles000001",
          collectionName: "profiles",
        },
      },
    };
    expect(mod.AuthorsResponseSchema.safeParse(author).success).toBe(true);
    // an array here must fail (it's a unique single back-relation)
    const asArray = {
      ...author,
      expand: { profiles_via_author: [author.expand.profiles_via_author] },
    };
    expect(mod.AuthorsResponseSchema.safeParse(asArray).success).toBe(false);
  });
});
